import { useCallback } from 'react';
import { useIntl } from 'react-intl';
import { useDispatch } from 'react-redux';

import performanceToolEmptyTimePeriodIllustration from 'assets/performance-tool-empty-time-period.svg';
import { usePageFilterData, usePageFilterManagement } from 'hooks';
import { resetAndApplyDefaults } from 'redux/slices/filters';

import {
  PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT,
  PERFORMANCE_TOOL_PAGE_NAME,
  WATERFALL_RESET_EVENT,
} from '../../constants';
import {
  StyledActionsWrapper,
  StyledCopyGroup,
  StyledDescription,
  StyledIllustrationWrapper,
  StyledKpiDrillDownEmptyCard,
  StyledKpiDrillDownEmptyContainer,
  StyledTitle,
} from './KpiDrillDownEmptyTimePeriodState.styles';

interface KpiDrillDownEmptyTimePeriodStateProps {
  dataTestId?: string;
}

export const KpiDrillDownEmptyTimePeriodState: React.FC<
  KpiDrillDownEmptyTimePeriodStateProps
> = ({ dataTestId = 'kpi-drill-down-empty-time-period-state' }) => {
  const { formatMessage } = useIntl();
  const dispatch = useDispatch();
  const { defaults } = usePageFilterData(PERFORMANCE_TOOL_PAGE_NAME);
  const { apply } = usePageFilterManagement(PERFORMANCE_TOOL_PAGE_NAME);

  const handleResetFilters = useCallback(() => {
    if (!defaults || Object.keys(defaults).length === 0) {
      return;
    }

    dispatch(resetAndApplyDefaults({ form: defaults, quickForm: defaults }));
    apply();

    globalThis.dispatchEvent(new Event(WATERFALL_RESET_EVENT));
  }, [apply, defaults, dispatch]);

  const handleSelectNewTimePeriod = useCallback(() => {
    globalThis.dispatchEvent(
      new Event(PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT),
    );
  }, []);

  return (
    <StyledKpiDrillDownEmptyCard data-testid={dataTestId}>
      <StyledKpiDrillDownEmptyContainer>
        <StyledIllustrationWrapper>
          <img
            src={performanceToolEmptyTimePeriodIllustration}
            alt=""
            aria-hidden="true"
            data-testid={`${dataTestId}-illustration`}
          />
        </StyledIllustrationWrapper>

        <StyledCopyGroup>
          <StyledTitle data-testid={`${dataTestId}-title`}>
            {formatMessage({
              id: 'ValueCreation.PerformanceTool.kpiDrillDownEmptyTimePeriod.title',
            })}
          </StyledTitle>

          <StyledDescription data-testid={`${dataTestId}-description`}>
            {formatMessage({
              id: 'ValueCreation.PerformanceTool.kpiDrillDownEmptyTimePeriod.description',
            })}
          </StyledDescription>
        </StyledCopyGroup>

        <StyledActionsWrapper>
          <button
            type="button"
            data-variant="secondary"
            data-testid={`${dataTestId}-reset-filters`}
            onClick={handleResetFilters}
          >
            {formatMessage({
              id: 'ValueCreation.PerformanceTool.kpiDrillDownEmptyTimePeriod.resetFilters',
            })}
          </button>
          <button
            type="button"
            data-variant="primary"
            data-testid={`${dataTestId}-select-time-period`}
            onClick={handleSelectNewTimePeriod}
          >
            {formatMessage({
              id: 'ValueCreation.PerformanceTool.kpiDrillDownEmptyTimePeriod.selectTimePeriod',
            })}
          </button>
        </StyledActionsWrapper>
      </StyledKpiDrillDownEmptyContainer>
    </StyledKpiDrillDownEmptyCard>
  );
};
